// Define la semana del reporte: por defecto la última semana COMPLETA (lunes a domingo), con fechas de Argentina.
const SLUG = 'cortado-en-jarrito';     // cliente del CRM (columna slug)
const DESDE_MANUAL = '';               // para una corrida a mano: 'AAAA-MM-DD' (y HASTA_MANUAL también)
const HASTA_MANUAL = '';

const ahoraAR = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' }));
const f = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const dow = (ahoraAR.getDay() + 6) % 7;                 // 0 = lunes
const domingo = new Date(ahoraAR); domingo.setDate(ahoraAR.getDate() - dow - 1);
const lunes = new Date(domingo); lunes.setDate(domingo.getDate() - 6);
const desde = DESDE_MANUAL || f(lunes);
const hasta = HASTA_MANUAL || f(domingo);

// Número de semana ISO de la fecha "hasta": es la versión del archivo (V47, V48...), así nunca se pisa un reporte anterior.
const t = new Date(Date.UTC(+hasta.slice(0, 4), +hasta.slice(5, 7) - 1, +hasta.slice(8, 10)));
t.setUTCDate(t.getUTCDate() + 4 - (t.getUTCDay() || 7));
const semana = Math.ceil((((t - new Date(Date.UTC(t.getUTCFullYear(), 0, 1))) / 86400000) + 1) / 7);

return [{ json: { slug: SLUG, desde, hasta, semana, version: 'V' + semana,
  archivo: `Reporte semanal ${SLUG} ${desde} a ${hasta} V${semana}.xlsx` } }];

// Arma la tabla del reporte: una fila por comunidad y una de total. Los números vienen YA CALCULADOS por el CRM (reporte_semanal): acá no se calcula nada.
const sem = $('Definir semana').first().json;
const filas = $input.all().map((i) => i.json);
const num = (v) => (v === null || v === undefined || v === '' ? '' : Number(v));
const dia = (v) => (v ? String(v).slice(0, 10) : '');
const salida = filas.map((r) => ({ json: {
  'Semana': sem.version, 'Desde': sem.desde, 'Hasta': sem.hasta,
  'Comunidad': r.comunidad,
  'Inversión': num(r.inversion), 'Chats de Meta': num(r.conversaciones), 'Clics en el enlace': num(r.clics_enlace),
  'Entradas al flow': num(r.entradas), 'Cobertura (%)': num(r.cobertura_pct), 'Costo por entrada': num(r.costo_por_entrada),
  'Última carga de miembros': dia(r.ultima_carga), 'Días sin carga': num(r.dias_sin_carga),
  'Miembros: desde': dia(r.miembros_desde), 'Miembros: hasta': dia(r.miembros_hasta),
  'Miembros al inicio': num(r.miembros_inicio), 'Nuevos': num(r.nuevos), 'Bajas': num(r.bajas), 'Miembros al final': num(r.miembros_fin),
  'CRR (%)': num(r.crr_pct), 'Churn (%)': num(r.churn_pct), 'Las cargas cuadran': r.cuadra === null ? '' : (r.cuadra ? 'Sí' : 'No'),
  'Inversión del intervalo': num(r.inversion_intervalo), 'Entradas del intervalo': num(r.entradas_intervalo),
  'Costo por miembro nuevo': num(r.cpmn), 'Tasa de triaje (%)': num(r.triaje_pct),
} }));
return salida;

// Texto del correo con lo más importante. Solo lee números ya calculados; si algo falta, lo dice.
const sem = $('Definir semana').first().json;
const filas = $('Armar Excel').all().map((i) => i.json);
const tot = filas.find((r) => r['Comunidad'] === 'Total del cliente') || {};
const comunidades = filas.filter((r) => r['Comunidad'] !== 'Total del cliente');
const dinero = (v) => v === '' ? 'sin dato' : '$' + Number(v).toLocaleString('es-AR', { maximumFractionDigits: 0 });
const pct = (v) => v === '' ? 'no calculable' : Number(v).toLocaleString('es-AR', { maximumFractionDigits: 1 }) + ' %';
const viejas = comunidades.filter((r) => r['Días sin carga'] !== '' && r['Días sin carga'] > 8).map((r) => `${r['Comunidad']} (${r['Días sin carga']} días)`);
const lineas = comunidades.map((r) => `<li><b>${r['Comunidad']}</b>: inversión ${dinero(r['Inversión'])}, ${r['Entradas al flow']} entradas, cobertura ${pct(r['Cobertura (%)'])}, CRR ${pct(r['CRR (%)'])}, churn ${pct(r['Churn (%)'])}</li>`).join('');
const html = `<p>Reporte semanal del ${sem.desde} al ${sem.hasta} (${sem.version}).</p>
<p><b>Total:</b> inversión ${dinero(tot['Inversión'])}, ${tot['Entradas al flow'] ?? 0} entradas al flow, cobertura ${pct(tot['Cobertura (%)'])}, CRR ${pct(tot['CRR (%)'])}.</p>
<ul>${lineas}</ul>
${viejas.length ? `<p style="color:#b45309"><b>Atención:</b> datos de miembros viejos en ${viejas.join(', ')}. El CRR de esas comunidades no está al día.</p>` : ''}
<p>El Excel adjunto tiene el detalle. Los números salen del CRM; lo que no se pudo calcular figura vacío o como "no calculable".</p>`;
return [{ json: { asunto: `Reporte semanal ${sem.slug} ${sem.version}`, html }, binary: $input.first().binary }];
